#ifndef __TBA_DISMOUNT_PROC_ARM_ARMOPERANDCODECA32_H
#define __TBA_DISMOUNT_PROC_ARM_ARMOPERANDCODECA32_H

/*
 * ArmOperandCodecA32.h
 *
 * The schemes of the AArch32 (A32 and T32) operand kinds of ArmOperandCodec:
 * the m_flags and m_extra values of the specs of the AArch32 tables. The
 * tables (gArmA32EncodingTable and the others of ArmEncodingTable.h) are
 * generated by tests/arm/tools/gen_aarch32_tables.py from the LLVM
 * description of the instruction set, and the schemes are the operand
 * classes of it: each scheme names the fields of an operand class and the
 * way the formatter (ArmNotationA32.cpp) prints it.
 *
 * The decoded operands of AArch32 (ArmDecodedOperand):
 *   - general purpose register: KIND_REGISTER with m_register
 *     ARM_REG_R0 + n; a pair (ldrd) KIND_REGISTER_LIST with m_count 2 and
 *     no m_registerMask; a register list (ldm) KIND_REGISTER_LIST with the
 *     m_registerMask, m_isExplicit for the '^' of the user mode forms and
 *     m_addressing ADDRESSING_PRE_INDEX for the '!' of the register ("r0!")
 *   - a shifted register: KIND_SHIFTED_REGISTER with the shift
 *   - memory: KIND_MEMORY. The base m_base, the index register m_index (or
 *     ARM_NO_REGISTER) shifted by m_shift / m_shiftAmount, the offset m_offset
 *     which is a magnitude: the sign is m_isSubtract. m_addressing is the
 *     offset, pre or post index form. m_isHex prints the immediate in
 *     hexadecimal and m_isExplicit prints a zero offset ("[r0, #0]!")
 *   - an option: KIND_OPTION with the ArmA32OptionScheme in m_optionScheme;
 *     the text of a value which has no name is in m_name
 *
 * Author: Elad Raz <e@eladraz.com>
 */
#include "xStl/types.h"
#include "xStl/data/string.h"
#include "dismount/proc/arm/ArmEncodingTable.h"
#include "dismount/proc/arm/ArmOpcode.h"

namespace armdis {

/*
 * ARM_KIND_GPR of AArch32: m_position is the register field, m_extra its
 * width (4, or 3 for the T16 low registers), m_flags & ARM_A32_GPR_CLASS_MASK
 * the register class. The classes of LLVM which only soft fail (r15 for
 * GPRnopc, sp for GPRnosp) are plain registers: the decoder decodes them.
 */
enum ArmA32GprClass {
    // Any of r0-r15
    ARM_A32_GPR_ANY,
    // Only sp (r13): the encoding is invalid otherwise (add r0, sp, ...)
    ARM_A32_GPR_SP_ONLY,
    // The registers of a tail call: r0-r3, r9 and r12 (tcGPR)
    ARM_A32_GPR_TAIL_CALL,
    // r13 is invalid (GPRwithZRnosp)
    ARM_A32_GPR_NO_SP,
    // r15 is printed apsr_nzcv (mrc, vmrs)
    ARM_A32_GPR_APSR,
    // r15 is printed zr (the CSEL family)
    ARM_A32_GPR_ZR,
    // A pair of registers Rt, Rt + 1 (ldrd): the second is r15 at most, so r15
    // is invalid for the first one; printed "r0, r1"
    ARM_A32_GPR_PAIR_NEXT,
    // A pair of the GPRPair class (ldrexd): r0 - r12 as the first register
    // (r13 is invalid); printed "r0, r1"
    ARM_A32_GPR_PAIR_CLASS,
    // The base register of a coprocessor access or lr (blx lr)
    ARM_A32_GPR_CLASS_MASK = 0x0F,
    // The register is followed by '!' (the writeback of ldm / stm)
    ARM_A32_GPR_WRITEBACK = 0x10,
    // The T16 ldm: the '!' is printed unless the register is in the list
    ARM_A32_GPR_WRITEBACK_UNLESS_LISTED = 0x20,
    // T32 rev / clz...: the register is in the encoding twice (bits 16-19 and
    // 0-3) and LLVM decodes the OR of the two
    ARM_A32_GPR_DUPLICATE = 0x40
};

/*
 * ARM_KIND_GPR_LIST of AArch32: m_position 0, m_extra the width of the mask
 * (16, or 8 for the T16 lists); m_flags ArmA32ListFlags
 */
enum ArmA32ListFlags {
    // The user mode form: ldm r0, {r1, r2}^
    ARM_A32_LIST_CARET   = 0x01,
    // The T16 push / pop: bit 8 is lr (push) or pc (pop): the register in
    // m_flags >> 4 (14 or 15)
    ARM_A32_LIST_EXTRA   = 0x02,
    // The T32 lists: sp (13) can't be in it, and pc (15) and lr (14) not
    // together in a push
    ARM_A32_LIST_T32     = 0x04,
    // The T32 stm / push: the bits 13 and 15 are not in the encoding, the
    // fields are 0-12 and 14
    ARM_A32_LIST_T32_STORE = 0x08
};

/*
 * ARM_KIND_SHIFTED_REGISTER of AArch32: m_position the register Rm, m_extra
 * an ArmA32ShiftScheme
 */
enum ArmA32ShiftScheme {
    // A32 so_reg_imm: type at 5-6, imm5 at 7-11 (ror #0 is rrx, lsr / asr #0
    // is #32)
    ARM_A32_SHIFT_SO_IMM,
    // A32 so_reg_reg: type at 5-6, Rs at 8-11
    ARM_A32_SHIFT_SO_REG,
    // pkhbt: lsl #imm5 at 7 (nothing if 0)
    ARM_A32_SHIFT_PKH_LSL,
    // pkhtb: asr #imm5 at 7 (0 is #32)
    ARM_A32_SHIFT_PKH_ASR,
    // ssat / usat: sh at 6 (asr), imm5 at 7 (nothing for lsl #0)
    ARM_A32_SHIFT_SAT,
    // sxtb / uxtab...: ror #8 * rot, rot at 10-11 (nothing for 0)
    ARM_A32_SHIFT_ROTATE,
    // T32 t2_so_reg: type at 4-5, imm3:imm2 at 12 and 6
    ARM_A32_SHIFT_T2_IMM,
    // T32 pkhbt / pkhtb / ssat shifts: the same fields
    ARM_A32_SHIFT_T2_PKH_LSL,
    ARM_A32_SHIFT_T2_PKH_ASR,
    ARM_A32_SHIFT_T2_SAT,
    // T32 sxtb.w: rot at 4-5
    ARM_A32_SHIFT_T2_ROTATE,
    ARM_A32_SHIFT_SCHEMES_COUNT
};

/*
 * ARM_KIND_A32_MEMORY: m_position is the base register field, m_extra the
 * addressing scheme, m_flags the ARM_A32_MEM_* bits (the scale in the bits
 * 0-2 as for the immediates)
 */
enum ArmA32AddressScheme {
    // The addressing forms of the A32 loads and stores (the base Rn at 16, U
    // at 23): [Rn, #+/-imm12], with the pre index ! when m_flags has
    // ARM_A32_MEM_PRE
    ARM_A32_ADDR_IMM12,
    // [Rn, +/-Rm{, shift #imm}]: Rm at 0, type at 5, imm5 at 7 (ldst_so_reg)
    ARM_A32_ADDR_SO_REG,
    // A32 addressing mode 3 (ldrh, ldrd): [Rn, #+/-imm8] / [Rn, +/-Rm], the
    // bit 22 selects the immediate
    ARM_A32_ADDR_MODE3,
    // addressing mode 3 post indexed: [Rn], #+/-imm8 or [Rn], +/-Rm
    ARM_A32_ADDR_MODE3_POST,
    // addressing mode 2 post indexed: [Rn], #+/-imm12 (bit 25 clear) or
    // [Rn], +/-Rm{, shift #imm} (bit 25 set)
    ARM_A32_ADDR_MODE2_POST_IMM,
    ARM_A32_ADDR_MODE2_POST_REG,
    // [Rn] (ldrex, lda...)
    ARM_A32_ADDR_BASE,
    // The unprivileged halfword accesses post indexed: [Rn], #+/-imm8
    ARM_A32_ADDR_POST_IMM8,
    // [Rn], +/-Rm
    ARM_A32_ADDR_POST_REG,
    // The coprocessor loads and stores: [Rn, #+/-imm8 * 4]{!} (the offset and
    // pre indexed forms by ARM_A32_MEM_PRE), [Rn], #+/-imm8 * 4 (post),
    // [Rn], {option} (the unindexed form)
    ARM_A32_ADDR_MODE5,
    ARM_A32_ADDR_MODE5_POST,
    ARM_A32_ADDR_MODE5_OPTION,
    // The Thumb forms: [Rn, #imm5 * 1/2/4] (T16 ldr / str / ldrb / ldrh with
    // an immediate; the scale is in m_flags & ARM_SPEC_SCALE_MASK), Rn at
    // m_position and imm5 at 6
    ARM_A32_ADDR_T16_IMM5,
    // [Rn, Rm] with Rm at 6 (T16)
    ARM_A32_ADDR_T16_REG,
    // [sp, #imm8 * 4] and [pc, #imm8 * 4] (T16)
    ARM_A32_ADDR_T16_SP,
    ARM_A32_ADDR_T16_PC,
    // T32: [Rn, #imm12] (Rn at 16, imm12 at 0)
    ARM_A32_ADDR_T32_IMM12,
    // [Rn, #-imm8] (P=1, U=0, W=0) and [Rn, #imm8] ...: the T32 imm8 forms
    // with P U W at 10 9 8: [Rn, #+/-imm8]{!} and [Rn], #+/-imm8
    ARM_A32_ADDR_T32_IMM8,
    // [Rn, Rm{, lsl #imm2}] Rm at 0, imm2 at 4
    ARM_A32_ADDR_T32_REG,
    // [Rn, #+/-imm8 * 4]{!} (ldrd / strd) and [Rn], #+/-imm8 * 4
    ARM_A32_ADDR_T32_IMM8S4,
    // [Rn, Rm] and [Rn, Rm, lsl #1] (tbb / tbh)
    ARM_A32_ADDR_T32_TBB,
    ARM_A32_ADDR_T32_TBH,
    // [Rn, #imm8 * 4] (ldrex / strex), Rn at 16 and imm8 at 0: the scale is 2
    ARM_A32_ADDR_T32_IMM0_1020S4,
    // The post indexed forms: [Rn], #+/-imm8 and [Rn], #+/-imm8 * 4
    ARM_A32_ADDR_T32_IMM8_POST,
    ARM_A32_ADDR_T32_IMM8S4_POST,
    // [pc, #+/-imm12], U at 23 (the T32 literal loads); no register field
    ARM_A32_ADDR_T32_LITERAL,
    ARM_A32_ADDR_SCHEMES_COUNT
};

// m_flags of ARM_KIND_A32_MEMORY (above the scale bits 0-2)
enum {
    // The pre indexed form, printed "]!"
    ARM_A32_MEM_PRE = 0x08,
    // The T32 forms which use the P / U / W bits of the encoding
    ARM_A32_MEM_UNPRIVILEGED = 0x10,
    // ARM_A32_ADDR_T32_IMM8: the offset is always added (ldrt) / always
    // subtracted (pld [r0, #-4]); without them the U bit at 9 selects
    ARM_A32_MEM_POS = 0x20,
    ARM_A32_MEM_NEG = 0x40,
    // The T32 stores: a pc base register is invalid
    ARM_A32_MEM_NO_PC = 0x80
};

/*
 * ARM_KIND_A32_FIELD: operands made of several fields. The position and the
 * width of each field are fixed by the scheme (m_position is the main one)
 */
enum ArmA32FieldScheme {
    // bkpt / hlt / hvc / udf: imm12 at 8 : imm4 at 0, in hexadecimal
    ARM_A32_FIELD_IMM16_SPLIT,
    // movw / movt: imm4 at 16 : imm12 at 0, in hexadecimal
    ARM_A32_FIELD_MOVW_IMM16,
    // bfc / bfi: the lsb at 7 (5 bits), decimal
    ARM_A32_FIELD_BF_LSB,
    // bfc / bfi: the width msb at 16 - lsb at 7 + 1, decimal
    ARM_A32_FIELD_BF_WIDTH,
    // ssat / ssat16 / sbfx / ubfx width...: the field + 1, in hexadecimal
    ARM_A32_FIELD_PLUS_ONE,
    // lsl / lsr / asr / ror #imm5 at 7 (0 is #32), decimal
    ARM_A32_FIELD_SHIFT_AMOUNT,
    // The T32 fields: addw / subw imm12 (i at 26, imm3 at 12, imm8 at 0), hex
    ARM_A32_FIELD_T32_IMM12,
    // movw / movt: imm4 at 16 : i at 26 : imm3 at 12 : imm8 at 0, hex
    ARM_A32_FIELD_T32_MOVW_IMM16,
    // hvc / udf: imm4 at 16 : imm12 at 0, hex
    ARM_A32_FIELD_T32_IMM16,
    // lsl / lsr / asr / ror #imm3:imm2 (at 12 and 6, 0 is #32), hex
    ARM_A32_FIELD_T32_SHIFT_AMOUNT,
    // The T16 lsr / asr #imm5 at m_position (0 is #32), hex
    ARM_A32_FIELD_T16_SHIFT_AMOUNT,
    // sbfx / ubfx lsb: imm3 at 12 : imm2 at 6, hex
    ARM_A32_FIELD_T32_LSB,
    // bfi / bfc lsb (imm3:imm2) and width (msb at 0), decimal
    ARM_A32_FIELD_T32_BF_LSB,
    ARM_A32_FIELD_T32_BF_WIDTH,
    // adr.w: +/-imm12 (i at 26, imm3 at 12, imm8 at 0), sign at 21 and 23
    ARM_A32_FIELD_T32_ADR,
    ARM_A32_FIELD_SCHEMES_COUNT
};

/*
 * ARM_KIND_A32_OPTION: the named values. The disassembler produces
 * ArmDecodedOperand::KIND_OPTION with m_optionScheme the scheme and
 * m_option the field value; m_position (the field) and m_extra (the scheme)
 */
enum ArmA32OptionScheme {
    // dmb / dsb: 4 bits, sy / st / ld / ish...; PreV8 the ld forms have no name
    ARM_A32_OPT_BARRIER,
    // isb: "sy" for 15
    ARM_A32_OPT_ISB,
    // The coprocessor number p0-p15 and register c0-c15
    ARM_A32_OPT_COPROC,
    ARM_A32_OPT_CREG,
    // The cps interrupt flags: a i f combinations (3 bits), none for 0
    ARM_A32_OPT_IFLAGS,
    // setend: bit 9, le / be
    ARM_A32_OPT_ENDIAN,
    // msr: the mask 4 bits at 16 and R at 22: apsr_nzcvq, cpsr_fc, spsr_x...
    ARM_A32_OPT_MSR_MASK,
    // mrs / msr banked registers: r8_usr... (R at 22, m at 16, m1 at 8)
    ARM_A32_OPT_BANKED,
    // The "{imm8}" option of ldc / stc unindexed
    ARM_A32_OPT_COPROC_OPTION,
    ARM_A32_OPT_SCHEMES_COUNT
};

// m_flags of ARM_KIND_A32_OPTION with ARM_A32_OPT_COPROC
enum {
    // ldc / stc: ARMv8 allows cp14 only
    ARM_A32_COPROC_CP14_V8 = 0x01
};

// m_flags of ARM_KIND_A32_MODIFIED_IMMEDIATE
enum {
    // The value is printed unsigned (mov pc, #imm; msr spsr, #imm)
    ARM_A32_MODIMM_UNSIGNED = 0x01,
    // The T32 form: i at 26, imm3 at 12, imm8 at 0 (the splat and the rotation
    // of ThumbExpandImm), printed in hexadecimal
    ARM_A32_MODIMM_T32 = 0x02
};

// m_flags of ARM_KIND_A32_OPTION with ARM_A32_OPT_BANKED / ARM_A32_OPT_MSR_MASK
enum {
    // T32: R at 20, m1 at 4 and m at 16 (mrs) / at 8 (msr)
    ARM_A32_BANKED_T32_MRS = 0x02,
    ARM_A32_BANKED_T32_MSR = 0x04,
    // T32 msr: the mask at 8 (4 bits) and R at 20
    ARM_A32_MSR_T32 = 0x02
};

/*
 * ARM_KIND_A32_FIXED: the text of the operand
 */
enum ArmA32FixedText {
    ARM_A32_FIXED_APSR,
    ARM_A32_FIXED_SPSR,
    ARM_A32_FIXED_SP,
    ARM_A32_FIXED_LR,
    ARM_A32_FIXED_CSYNC,
    ARM_A32_FIXED_ZERO,
    ARM_A32_FIXED_SP_WRITEBACK,
    // The operand which LLVM prints for rfe: the addressing mode and the '!'
    ARM_A32_FIXED_RFE_DA,
    ARM_A32_FIXED_RFE_IA,
    ARM_A32_FIXED_RFE_DB,
    ARM_A32_FIXED_RFE_IB,
    ARM_A32_FIXED_PC,
    ARM_A32_FIXED_R12,
    ARM_A32_FIXED_HEX_ZERO,
    ARM_A32_FIXED_COUNT
};

/*
 * ARM_KIND_A32_MNEMONIC_PART
 */
enum ArmA32MnemonicPart {
    // it, itt, ite...: the letters from the mask (4 bits at m_position) and
    // the firstcond (bit 0 of it at 4)
    ARM_A32_PART_IT_MASK,
    // cps: ie / id from imod at 18 (2 bits): 2 is "ie", 3 is "id", 0 nothing
    ARM_A32_PART_CPS_IMOD,
    // T32 cps: the imod at 9 (2 bits)
    ARM_A32_PART_CPS_IMOD_T32,
    // T16 cps: ie (bit 4 clear) / id (bit 4 set)
    ARM_A32_PART_CPS_IMOD_T16,
    ARM_A32_PART_COUNT
};

/*
 * ARM_KIND_BRANCH_TARGET of AArch32: m_position the field, m_extra its width
 * and m_flags the scheme
 */
enum ArmA32BranchScheme {
    // A32 b / bl: imm24 * 4 + 8
    ARM_A32_BRANCH_B,
    // A32 blx: imm24 * 4 + H * 2 + 8, H at 24, the target is Thumb
    ARM_A32_BRANCH_BLX,
    // T16 b: imm11 * 2 + 4; b<c>: imm8 * 2 + 4; cbz / cbnz: i at 9 : imm5 at 3
    // * 2 + 4
    ARM_A32_BRANCH_T16_B,
    ARM_A32_BRANCH_T16_BCC,
    ARM_A32_BRANCH_T16_CB,
    // T32 b.w / bl: S at 26, J1 at 13, J2 at 11, imm10 at 16, imm11 at 0;
    // blx: the same with the target aligned to 4 and imm11 of 10 bits
    ARM_A32_BRANCH_T32_BL,
    ARM_A32_BRANCH_T32_BLX,
    // T32 b<c>.w: S at 26, J2 at 11, J1 at 13, imm6 at 16, imm11 at 0
    ARM_A32_BRANCH_T32_BCC
};

// m_flags of the mnemonic parts
enum {
    // ARM_KIND_CONDITION_MNEMONIC: the condition is the one of the it block
    // (T16 / T32 instructions which are not conditional by themselves)
    ARM_A32_COND_IT = 0x01,
    // The Advanced SIMD instructions: unconditional in A32, the condition of
    // the it block in T32
    ARM_A32_COND_IT_ONLY = 0x02,
    // ARM_KIND_CONDITION (the firstcond of it): 1111 is al
    ARM_A32_COND_FIRSTCOND = 0x02,
    // ARM_KIND_SETS_FLAGS: the T16 instruction sets the flags outside of an
    // it block ("adds"), and doesn't inside one
    ARM_A32_SETS_FLAGS_OUTSIDE_IT = 0x01
};

/*
 * The functions of the AArch32 area of the codec. Used by ArmOperandCodec.cpp
 * and the formatter
 */
bool decodeA32(const ArmOperandSpec& spec,
               uint32 encoding,
               const ArmCodecContext& context,
               ArmDecodedOperand& operand);
bool encodeA32(const ArmOperandSpec& spec,
               const ArmDecodedOperand& operand,
               const ArmCodecContext& context,
               uint32& encoding);

// The area functions of the memory, the Thumb forms and the Advanced SIMD and
// floating point kinds (ArmOperandCodecA32Memory.cpp, ...Thumb.cpp, ...Simd.cpp)
bool decodeA32Memory(const ArmOperandSpec& spec, uint32 encoding,
                     const ArmCodecContext& context, ArmDecodedOperand& operand);
bool encodeA32Memory(const ArmOperandSpec& spec, const ArmDecodedOperand& operand,
                     const ArmCodecContext& context, uint32& encoding);
bool decodeA32ThumbMemory(const ArmOperandSpec& spec, uint32 encoding,
                          const ArmCodecContext& context, ArmDecodedOperand& operand);
bool encodeA32ThumbMemory(const ArmOperandSpec& spec, const ArmDecodedOperand& operand,
                          const ArmCodecContext& context, uint32& encoding);
bool decodeA32ThumbBranch(const ArmOperandSpec& spec, uint32 encoding,
                          const ArmCodecContext& context, ArmDecodedOperand& operand);
bool encodeA32ThumbBranch(const ArmOperandSpec& spec, const ArmDecodedOperand& operand,
                          const ArmCodecContext& context, uint32& encoding);
bool decodeA32Simd(const ArmOperandSpec& spec, uint32 encoding,
                   const ArmCodecContext& context, ArmDecodedOperand& operand);
bool encodeA32Simd(const ArmOperandSpec& spec, const ArmDecodedOperand& operand,
                   const ArmCodecContext& context, uint32& encoding);

// The banked registers (mrs / msr): the name of an encoding R:m1:m (6 bits),
// NULL if it has none, and the encoding of a name. Generated with the tables
const char* getA32BankedName(uint encoding);
bool findA32BankedRegister(const cString& name, uint& encoding);

// The mnemonic parts of AArch32 (condition, s, cps ie...)
cString decodeMnemonicPartA32(const ArmOperandSpec& spec,
                              uint32 encoding,
                              const ArmCodecContext& context);
bool encodeMnemonicPartA32(const ArmOperandSpec& spec,
                           cString& suffix,
                           const ArmCodecContext& context,
                           uint32& encoding);

// The text of an AArch32 operand (ArmNotationA32.cpp)
cString formatOperandA32(const ArmDecodedOperand& operand);

// Return the text of an option value, NULL if it has no name
const char* getA32OptionName(uint scheme, uint value);

// Return the fixed text
const char* getA32FixedText(uint text);

} // namespace armdis

#include "dismount/proc/arm/ArmOperandCodecA32Simd.h"

#endif // __TBA_DISMOUNT_PROC_ARM_ARMOPERANDCODECA32_H
